'use client'
// Help Centre -> Step-by-step guide (app/help/page.tsx): plain-English how-to for people using the platform.
import { useState } from 'react'

const SECTIONS: { id: string; title: string; steps: string[]; pic?: { src: string; alt: string } }[] = [
  { id: 'start', title: 'Getting started', steps: [
    'Open Settings, then My Account, and check your name and email are right.',
    'Under Payments, check your plan. Under Team Management, invite the people who will use Novourq with you and choose what each of them can see. Edit a team member to give them modules, then untick any Human Intelligence Hub tab you want locked for them: Novourq Cloud AI, Data Hub, Company Documents, CRM, Landlord Leads, Client Properties, Invoices, Approvals, Announcements, Activity Log and more. Only admins can unlock a tab again. Team members work on the company\'s own records everywhere, including Marketing and Company Documents.',
    'Team Management also shows Novourq Cloud AI, the one AI that works for your whole business. It is the same for every account. You see its skills and when it hands over to a person, but you do not add or edit AI staff.',
    'Set up your email branding in Invoice settings: add your company name, logo and contact details. Every email Novourq sends for you uses them, so it looks like it came from your company.',
    'Add your first properties in Real Estate Intelligence. Everything else builds on them.',
  ] },
  { id: 'rei', title: 'Real Estate Intelligence', steps: [
    'Where do I go? sits at the top of Real Estate Intelligence: pick a task such as Add a tenant, Check a tenant’s ID and income, Add a guest booking or Chase rent and press the area that fits. Property Management means we manage the property for the landlord, Estate Agency means we let or sell it for the landlord, Vacation Rentals means guest bookings. Hover an area name anywhere on the page to see what it means. Limits: it opens the page, it does not add the record for you, and it only shows the areas your role can open.',
    'Get started checklist: a new account sees it at the top of Real Estate Intelligence with four steps, choose your currency, add your first property, add the landlord who owns it, add a tenant. Press Open on a step to go to the right page. Steps tick off by themselves once a record exists, and the box disappears when all three are done. Press Hide to hide it on this device. Limits: it counts records across Property Management, Estate Agency and Vacation Rentals and only shows steps your role can open.',
    'Currency: Settings → Currency (admin only). Same page: choose your company time zone (UK, Ireland, Central Europe, UAE, Jamaica, US or Canada zones). It decides what today is for overdue invoices and rent, due dates, compliance expiry, Finance alerts and the dashboard; it starts on UK time. Pick the symbol your company uses, pound, US dollar, Jamaican dollar, euro, UAE dirham or Canadian dollar, and press Save. Rent, income, costs and totals across Property Management, Estate Agency, Vacation Rentals, Developments and At a glance then show that symbol. Limits: it only changes the symbol, amounts are shown exactly as entered and nothing is converted, Unit Profit and the plan prices stay in pounds, and the AI’s own reports still show pounds. Landlord and tenant portals show the symbol of the company they belong to. New invoices start in your currency and you can switch each one to pound, US dollar, Jamaican dollar, euro, UAE dirham or Canadian dollar; the overdue rent email, landlord statements and the tenant and landlord data summary use your symbol.',
    'Real Estate Intelligence is where your records live: properties, landlords, tenants, leases, rent, maintenance, compliance and more.',
    'Pick a module, then a tab. Each tab opens with a blue banner that says what it does.',
    'Add or edit records with the buttons on each tab. Novourq Cloud AI reads these records to do its work, so the more complete they are, the better it works.',
    'Legal and disputes (under Compliance) records eviction notices, arrears claims and deposit disputes with their next deadline, and the deadline also shows in Deadlines. It is a register only: it gives no legal advice and contacts no one. Referrals (under Lettings and sales) records who referred whom and any reward owed. Nothing is paid from it. Landlord Feedback and Tenant Feedback (under Lettings and sales) show the star ratings and comments that landlords and tenants write in the new Feedback tab of their own portals. Mark each Seen or Actioned. The team gets a bell notification for every new one. Press Reply to answer: the reply shows in their own Feedback tab and is also emailed to them (email and portal only, no texts). People only see their own feedback. Valuations (under Finance) records each property\'s value over time and the change since the last one.',
    'At a glance sits at the bottom of the Real Estate Intelligence page: headline tiles for Short term rentals, Lettings, Estate agency and Developments, such as occupancy, rent collected, arrears, viewings, budget spent and snags open. You only see the areas you can open, each tile opens its page, and it only reads what is already in Novourq. Estate agency has no offers or sales pipeline records yet, so there is no tile for them.',
    'Rent Reviews (under Lettings and sales) lists each lease\'s next review date with the current and proposed rent; use the buttons to mark the notice sent and agreed. It is a list and reminder only: it does not send the notice or change the rent. Service Charges (under Finance) records service charge, ground rent and sinking fund per property with who it is paid to and when it is due; press Mark paid, then Next period. Planned Maintenance (under Operations) holds recurring jobs such as boiler services; press Done to record it and set the next date. It does not raise repair jobs by itself. Each day Novourq Cloud AI checks Rent Reviews, Service Charges and Planned Maintenance and leaves one task listing what is due or overdue. It only lists: it never sends a notice, pays a charge or books a job. Switch each one on or off in Novourq Cloud AI under Agents. Emergency Contacts (under Operations) holds the plumber, electrician, gas engineer, key holder and out-of-hours numbers for a property or for all of them. Contractors (under Operations) opens your contractors and suppliers with their work orders.',
  ] },
  { id: 'hih', title: 'Human Intelligence Hub', steps: [
    'The Human Intelligence Hub covers your customers, team and finances: inbox, website chats, CRM, invoices, arrears, tasks, people and training.',
    'Use it for the day-to-day running of your company. Novourq Cloud AI works the same areas in the background.',
    'Where do I go? sits at the top of the hub. Pick the job you want to do, such as Reply to a customer, Chase rent, Pay an owner or Log a repair, and press the button to open the right page. Where a job has more than one page, each has its own button. You only see pages your role can open.',
    'At a glance is at the bottom of the hub. It shows what needs you today as tiles under Clients and sales, Money, Operations and Company, such as unread messages, approvals waiting, overdue rent payments, open repairs and tasks due. The numbers match the red badges on the menu. Press a tile to open that page. It shows counts only, not money amounts, and you only see tiles for pages your role can open.',
    'Enquiry form link: open Marketing and use the Enquiry form link card on the home page to copy the link for landlords and investors. They choose Guaranteed Rent, Short Let Partnership or Estate Property Management and submit; the enquiry lands in the CRM Pipeline at Enquiry. Admins can switch the link off. The same card also has One link for all landlords (app.thenovourq.com/landlords/…): existing landlords sign in to the owners portal and new ones open the enquiry form, so you only share one link; it follows the same on/off switch. It also has One link for all tenants (app.thenovourq.com/tenants): existing tenants go to the tenants portal and people looking for a home go to the property listings. It also has One link for representatives (app.thenovourq.com/representatives/…): staff sign in to the oversight portal, agents sign in to the agent portal and new agents sign up.',
    'Careers page: open Human Intelligence Hub, Team, Applications, then Open roles & careers link. Add your open roles, press Copy link and send it to candidates. They choose a role and apply; the application lands in Applications at Applied. Candidates can attach a CV (PDF or Word, up to 5 MB); it shows in the CV link column.',
    'Links to send people: all stock for rent is app.thenovourq.com/homes (Marketing, Listings tab, Copy link). Landlords and investors use the enquiry form (Marketing, Enquiry form link). Job candidates use the careers page (Team, Applications, Open roles & careers link). Landlord portals: /pm-owner-portal, /estate-owner-portal, /owner-portal. Tenant portals: /pm-tenant-portal, /estate-tenant-portal. Portal links are in Portal Access. Landlords and tenants need a portal login on their record to sign in.',
    'Agent portal: open Partners & Investors, Partners, Agent Programme, and copy the Agent sign-up link for new agents. They create a login and wait; press Activate on their row to approve. Approved agents sign in at the agent portal link, see their code, commission due, pending and paid, and log their own referrals: Place a renter, Send a guest, or List a property with us. Agents can switch the amounts they see between six currencies (display only, converted from pounds). Staff still screen referrals and mark commission paid.',
    'Create an agent login yourself: Agent Programme → Agents → Add agent (or Edit), fill in name and email, type a password of 8 or more characters in the Agent portal login box and press Save agent. This creates the login, activates the agent, and they sign in at the agent portal; for an agent who already has a login it sets a new password. To record what an agent has already made, press Log guest / tenant in the Referral pipeline, add the value and the Commission earned and say if it is paid; it counts in their Paid or Owed.',
    'Leaderboard: every approved agent sees a Leaderboard at the top of the agent portal ranking all of your company\'s active agents by confirmed commission; others appear as first name and initial with a relative bar, never amounts, and the agent sees their own position. Only your own company\'s agents are ranked. The Dashboard also shows two Agent leaderboard boxes under Automation by area: the staff view with names and commission amounts, and what agents see (first name and initial with a bar, no amounts).',
    'Website pricing: the prices on the website come from a two-line snippet (a div with id novourq-pricing plus a script loading https://app.thenovourq.com/pricing.js). It reads the live Stripe prices behind the monthly, one-time and founding-client plans, so the website always shows what Stripe charges, and Choose plan opens Stripe Checkout where the client signs up and pays. Change a price in Stripe and the website updates within a couple of minutes.',
    'Agent page on the website: its form sends each applicant to CRM (contact type agent, deal at Enquiry) and emails them the agent sign-up link to create their portal login.',
    'Virtual viewings: for tenants who cannot visit, open Marketing, then Listings, press a property and add walk-through videos under Virtual viewing videos (upload, or paste a YouTube or Vimeo link). Tenants watch them on the property\'s public page and can tick that they want a video call instead. Use an unlisted YouTube link for very large videos.',
    'Staff Training (Team) opens on Portal guides: a how-to for every tab with steps, pictures and video, a What\'s new box that lists recent changes, and search. Every new tab appears there on its own. Admins add pictures and videos to a tab (upload or paste a YouTube or Vimeo link); a tab without one shows the matching area video. Company training, the PDFs and videos you add for the team, is the second button.',
    'Under Team, HR Documents (Admin and HR Team only) keeps payslips, HR forms and contracts. Press Add NOVOURQ templates for the fillable payslip and proof of employment letter, add your own files, then Open / fill in to complete a form, Edit to rename or replace it with the finished copy, and Send to email it to the person. For documents that carry your own logo and name, Staff Centre, Documents, Templates, Add HR templates (admins) adds an editable Payslip and Proof of employment letter. Company Documents (Staff Centre) works the same way for incorporation papers, certificates and insurance. Limits: fillable fields are filled in your PDF viewer and saved as a PDF, then uploaded; calculated fields only work in Adobe Acrobat.',
    'Tenant checks from the tenant link: a tenant uploads their photo ID, right to rent result, proof of income, bank statements and references on their link (New client link, Tenant). Novourq Cloud AI reads the ID, right to rent, income and bank statement files and saves what it saw. Open Property Management → Compliance → Tenant Checks, press Add Checks (or Edit) on their lease, and a blue box shows what the AI read with a Fill the form from these button. Staff then check it against the documents and set Passed or Failed themselves, the AI never decides. Limits: photos or PDFs only, files over 8 MB are not read, blurry scans can come back with gaps, the right to rent share code is not checked against the Home Office, and the tenant needs a lease before the box shows. Estate Agency tenants are not read yet.',
    'Marketing, Services Pack holds the documents you send to show your services, including a welcome page for any landlord, co-host or tenant. The Company brochure now includes pages on the AI dashboard and the owners portal. Marketing, Emails, Mailing list lets you email everyone who opted in (all, or one type such as landlords), with an unsubscribe link in every email, and gives you a sign-up form to paste on your website. It can write the NOVOURQ marketing message for you and include Services Pack documents as pictures in the email, as a PDF button, or both. Under 1. Choose what to send, press the Landlord, Co-host or Tenant tab to see only that audience’s documents with the right ones ticked (All documents shows everything), or tick one or several yourself, press Create link and paste it into any email. The recipient opens a page with your logo and chooses each document to view. The Landlord tab also ticks the Welcome letter and Shortlet landlord onboarding form. The landlord Agreements (Master Lease, Estate agency) are never ticked for you: choose the one that fits the landlord before you create the link. The Co-host tab ticks the Shortlet co-host agreement and the Cohost detail sheet (fillable like the others). The agreements and onboarding form open as fillable pages on the link: the landlord clicks the shaded boxes to type or tick, enters their name and presses Submit to NOVOURQ, and it comes straight back to you. Each link in 3. Your links shows its NOVOURQ welcome message with the link under it, and Copy message copies it (the same welcome wording on every link), and the New client link message uses the same wording (with the 14 day validity). Find completed copies under Marketing, Services Pack, 3. Submitted documents and press Open completed PDF. To make another PDF fillable online, press Edit on it and tick Recipients fill this in online (the PDF must have form fields). After submitting, a landlord or co-host linked to a record sees Upload your documents: Landlord ID, Proof of ownership, Proof of address and Bank details for a landlord (ID, Owner’s consent, Proof of address and Bank details for a co-host), each as a PDF or photo up to 15 MB. They are filed on the same record in Documents, awaiting your approval, and you get a notification. Uploads only work right after submitting a form on that link. The Property (optional) box when you create a link is a drop-down of the properties in your portfolio (Property Management, Estate Agency and Vacation Rentals), with Not listed, type it for any other; the property you choose shows at the top of the recipient’s page; the New client link in Documents has its own Property (optional) box too, so a property can be added either way. It is a label only, it does not create or pick a property. Limits: no signature box yet, so signing still happens separately; the team (owner, admins, co-founders and the Property Management Team) is emailed with the completed PDF attached each time one arrives. To file it on a person’s record, choose Who is this link for? when you create the link: A new landlord or A new co-host (they are registered from the name and email they enter when they submit, or matched by email if they already exist; the Landlord and Co-host tabs pick this for you), or An existing landlord or co-host (search by name). Which section they go in follows the agreement they submit: the Estate agency agreement creates the landlord in Estate Agency, the Master Lease creates them in Property Management, and the Shortlet co-host agreement or any co-host link creates a co-host (no property). If the form has a property address, the property is created too and linked to them (with bedrooms and bathrooms when filled in); it is skipped when the address is blank or the same property already exists for that landlord. Each submission is then also added to their Documents (Management agreement for a landlord, Co-hosting agreement for a co-host, Other documents for the onboarding form), waiting for you to approve it in Staff Centre, Human Intelligence Hub, Documents. Links with no person picked only keep the copy in Submitted documents. Links stay live until you pause them, and you see opens and views for each. Upload your own PDFs with Add document. It does not put itself into campaign emails, so paste the link in.',
    'Under Team, Activity Log records who changed what and when. Admins and co-founders see every change in the company. Everyone else sees only their own. Changes made by Novourq Cloud AI or an automatic job show as "Novourq Cloud AI or system". Bank and ID details are never stored in it.',
  ] },
  { id: 'meetings-tax', title: 'Meetings and Tax Compliance', steps: [
    'Meetings: open Staff Centre, Schedule, Meetings. The Client booking link at the top is your own company\'s link. Share it by email, website or WhatsApp. When someone sends a request it appears under New request, you get a bell notification and an email, they are added to your CRM, and they receive a confirmation with your company name. Each company\'s link only reaches that company.',
    'Tax Compliance (admins only): open Staff Centre, Tax Compliance, then your company\'s tab and press Edit details to change the company name, currency, registration status, company number and tax note. You can also add bank accounts, tax headings and transfers. Nothing is filed or paid from here.',
  ] },
  { id: 'onboard-landlord', title: 'Onboard a landlord (staff step by step)', pic: { src: '/guide/hub-landlord-onboarding.jpg', alt: 'Human Intelligence Hub, Clients and sales: 1 Landlord Leads, 2 Owners, 3 Co-hosts, 4 Documents' }, steps: [
    'Get the enquiry: the landlord opens your landlords link or enquiry form (Staff Centre → Marketing → Enquiry form link). It lands in Staff Centre → Human Intelligence Hub → Clients and sales → CRM (Pipeline, Enquiry stage) and Landlord Leads (picture, number 1).',
    'Contact them, then move the lead along the Pipeline as you speak and book a valuation.',
    'Send the new client link: Human Intelligence Hub → Clients and sales → Owners & Tenants → Documents (picture, number 4) → New client link. Choose Who is this link for?, tick the agreement, press Create link and send it.',
    'The landlord fills in the agreement and uploads their ID, proof of ownership, proof of address and bank details. They are registered from the name and email they enter, and the copies file under their Documents.',
    'Add or check the owner: Human Intelligence Hub → Clients and sales → Owners & Tenants → Owners (picture, number 2), or Property Management → Landlords.',
    'If they have a co-host, open Co-hosts (picture, number 3) and add them.',
    'Approve the filed documents in Documents (number 4).',
    'Open Property Management → Landlords and press Onboarding on the landlord. Tick off the checklist, pick their named manager, set the agreement type, start and end dates, then press Mark as onboarded.',
    'Limits: there is no signature box yet, so signing happens separately. Only admins can unlock a locked tab.',
  ] },
  { id: 'earnings-checker', title: 'Landlord earnings checker', steps: [
    'Open Staff Centre, Landlord Leads, then Link & embed code. The link is your own company\'s earnings checker. Use it in ads, letters and with realtors, or paste the embed code into your website.',
    'A landlord enters their property details and gets an estimate by email, signed with your company name. The lead appears in Landlord Leads and your CRM and you get an alert. Their book-a-call button opens your own meeting link.',
    'Add ?src=facebook (or similar) to the link to see where each lead came from.',
  ] },
  { id: 'exchange-rates', title: 'Exchange rates and Unit Profit', steps: [
    'Set each property\'s currency when you add it (pound, US dollar, Jamaican dollar, euro, dirham or Canadian dollar).',
    'Open Real Estate Intelligence, Property Management, Exchange Rates and add how many of your company currency one unit of each other currency is worth. Update it when the rate changes.',
    'Unit Profit then shows each unit\'s income, head rent and running costs in your company currency. Head rent is taken as your company currency.',
  ] },
  { id: 'finance-currency', title: 'Finance currency', steps: [
    'Set your company currency in Settings, Currency. Finance then shows all totals, charts and owner payouts in it. Amounts in other currencies are converted at today\'s rate, listed under Exchange rates used on the Finance overview.',
  ] },
  { id: 'company-name', title: 'Your company name', steps: [
    'Set your company name in Invoice settings first. Text templates, marketing emails, signing links and documents all use it. If it is empty they say Property Management Team.',
  ] },
  { id: 'mailing-list', title: 'Mailing list and marketing emails', steps: [
    'Who is on the list: anyone who ticked the marketing box on the website popup, the website sign-up form or the enquiry form. Open Staff Centre, Marketing, Emails, then Mailing list (top right, next to Sending as) and press See who is on the list to see each person, where they signed up and when.',
    'To send: in the Mailing list window choose the Audience (everyone, or one type such as landlord), press Generate NOVOURQ message and edit the subject and wording if you want. {{first_name}} becomes each person\'s first name.',
    'Tick any Services Pack documents to include, grouped as AI platform and Property management (Company brochure, AI platform brochure, Lease your property to us, Furnished apartments, Vacation rental landlord pack). Under Send documents as choose Pictures plus a PDF button (recommended, because many people do not open PDFs), Pictures only, or PDF button only. Documents you upload yourself have no pictures and go as a PDF button.',
    'Press Send to N and confirm. Every email has an unsubscribe link, and anyone who unsubscribes is never emailed again. The email then shows as Sent in Emails.',
    'Ask Novourq Cloud AI to do it: say for example Send our marketing email to the mailing list with the brochure. It puts the email in Staff Centre, AI Command Centre, AI Approvals; open it, check the wording and the number of people, and press Approve. Nothing is sent until you approve, and this one cannot be switched to automatic.',
    'Platform leads: Anyone who creates a portal account (Start free trial) is saved in the NOVOURQ CRM as a platform lead; they join the Mailing list only if they ticked "Email me NOVOURQ product news and offers" on the sign-up form (never pre-ticked), so everyone on the list has agreed to it. For the platform audience, Generate NOVOURQ message writes a different message about the AI platform and ticks the AI platform brochure. a sign-up form carrying data-interest="platform" tags people as platform leads (the AI platform, not landlord services); they appear as their own audience in the Mailing list, separate from landlords. Sign-up form for your website: the bottom of the Mailing list window has a code to copy. Paste it where the form should appear (WordPress: a Custom HTML block). People who sign up are saved in your CRM as opted in and get a thank-you email.',
  ] },
  { id: 'ai', title: 'Novourq Cloud AI', steps: [
    'Novourq Cloud AI is one assistant with many skills, such as rent reminders, chasing invoices, replying to reviews and watching compliance dates.',
    'Novourq Cloud AI opens on a front page like the other hubs: Where do I go? for everyday tasks, a search box, pages grouped under headings with a line on each, and At a glance at the bottom. Inside a page, use ← Novourq Cloud AI at the top of the side menu to return.',
    'Open Workflows to see every skill. Switch a skill on or off, and choose "Send automatically" if you want it to send without waiting for you.',
    'Novourq Cloud AI has its own picture: the Novourq symbol as a glossy 3D mark on a blue glow. It plays as a short looping animation on the AI pages and the Dashboard AI panel. The Voice button is a light blue pill with the blue logo animating on it, with no box behind it. Devices set to reduce motion show the still picture. On the Dashboard, the NOVOURQ Walk video (showcasing our new AI technology) sits beside the Property map; Portfolio Performance and What Novourq Cloud AI did are the same size below, with Automation by area full width under them; press play to watch, it does not start by itself.',
    'Ask Novourq Cloud AI questions in plain words, typed or by voice, such as "What is overdue this week?". It reads today\'s rent, leases, maintenance, compliance, check-ins and invoices that you can see, and it never changes anything itself.',
    'Press "Run all now" to make the AI check everything straight away. It also runs by itself every day.',
    'Anything involving money or a legal contract always waits for your approval. You will find these in the approvals list.',
    'Ask the AI panel anything about the platform, such as "how do I add a tenant?", and it will answer or point you to the right page.',
  ] },
  { id: 'rent', title: 'Rent reminders', steps: [
    'Rent reminders go out in timed windows: before the due date, on the day, and then at stages after it if rent is late.',
    'Each reminder goes by email and to the tenant portal. No text messages are sent.',
    'You can see what was sent, and to whom, on the Reminders page in Finance.',
  ] },
  { id: 'chat', title: 'Website chat and viewings', steps: [
    'To connect your own email: open Human Intelligence Hub, then Inbox, then Email, then Mailbox settings. The quickest way is Sign in with Google or Sign in with Microsoft: you approve access on their own page and we never see your password. Otherwise an admin presses Add mailbox and types the address, then presses Connect. Pick where it is hosted (Gmail or Google Workspace, Microsoft 365 or Outlook, website hosting, or another provider), enter the password and press Connect. Gmail needs an app password and some Microsoft 365 accounts need their admin to allow IMAP and SMTP. Each mailbox can be shared with chosen team members. Your emails are stored encrypted and only your company sees them. Private mailboxes: a mailbox set to Private shows under Private (only you) in the Email sidebar, and only the people named in its Access can open it, admins included. Novourq Cloud AI box: it now sits at the bottom of every page (the same box as the dashboard), so you can ask a question without going back. It is read only and cannot change records. It is left off the Email page. New applicants card: the Dashboard shows people who have just applied, each with a Reply button that opens the acceptance, decline and interview messages. It is empty when nobody new is waiting.',
    'Email works on your phone too: the list of emails fills the screen, tap one to read it and press Back to Inbox to return. Press Folders to switch folder or mailbox, or open Email templates and Mailbox settings, and + New to write an email.',
    'To connect your own website chat: open Human Intelligence Hub, then Inbox, then Website Chats. Your own chat is set up automatically. Copy the one line of code under Add it to your website and paste it into your website footer or custom code area (WordPress, Elementor, Wix and Squarespace all have one). Chats then appear in the same tab and the AI answers using your settings.',
    'The website chat answers visitors, saves new leads and can book viewings.',
    'If your website has a careers form, each application appears in Human Intelligence Hub, then Team, then Applications. The applicant is also added to the CRM as a contact, with no deal, because they are not a sale. Reply to candidate: open a candidate and choose Acceptance, Decline or Interview invite. The wording is generated with their name and the role (the decline thanks them for their interest and says you will not be moving forward). Edit it, press Open in my email and send it yourself, or Copy; Set stage to moves them to Offered, Rejected or Interviewing. Limits: the portal does not send it for you, and it needs the candidate\'s email.',
    'Landlord and tenant feedback is under Real Estate Intelligence, Landlord Feedback or Tenant Feedback. Reply to any item: the person gets an email and sees your reply in the Feedback tab of their portal, where they can answer back. When feedback or an answer arrives, your owner, Admin, Co Founder and Property Management Team members are emailed with a link, and the item goes back to New.',
    'Signing documents with initials and dates: in Staff Centre, Documents, open a template and press + Initials box or + Date box where the signer must initial a section or pick a date (also + Insert blank for anything else). When you send it, the client opens the link on their phone, works through each box with a progress bar and a Fill my initials shortcut, then draws or types a signature and presses Finish and sign. The signed PDF shows signature, initials, dates, time and IP, is emailed to both sides, and for an owner or tenant is filed automatically in their Documents (and their portal). You can fill dates yourself before sending.',
    'Head lease documents: in Real Estate Intelligence, Head Leases, press Documents on a lease (shows how many of the 5 key documents are filled). Upload the master lease agreement, head lessor documents, landlord ID (with its expiry date), proof of ownership and change of electricity papers, plus any other files, as PDF, Word or photo up to 15 MB. Files are private to your company and open through links that last 5 minutes. Admins, Co Founders and property teams only. Landlord ID shows a warning 90 days before it expires. Owners and Tenants: press Documents on an owner or tenant for the same checklist (owners: ID, proof of ownership, management agreement, proof of address, bank details; tenants: tenancy agreement, ID, right to rent, proof of income, references). Each file is marked In portal or Staff only, and In portal files show automatically in that owner\'s Documents tab or that tenant\'s Documents tab, with a note of what is still needed. Estate Agency owners and tenants work the same way (Estate Agency, Landlords and Tenants, press Documents) and show in the Estate Agency portals. Document hub: owners and tenants can upload their own files in the portal Documents tab (Take photo or upload) and see a progress bar and what is still needed. Their uploads wait in Staff Centre, Documents, under To review, where you press View, Approve or Reject (a reason is required and is emailed to them). Rejected files show them why so they can upload again. Under Still missing documents, tick people and press Ask selected (or Chase on one person, or Ask them for missing documents inside a Documents window) to email what is missing with a link to their portal. After the first ask, reminders go out automatically every 3 days, up to 5, until they finish; people who were never asked get none. Reminders and asks need email set up and the person to have an email address. Old tenant files: in Property Management, Tenants, a Move to private button appears while older tenant files sit in the open All files list; it moves them (admins and Co Founders, 25 at a time) into each tenant\'s private Documents, keeping In portal choices. Lease signing: tenancy and lease sign pages now also ask the signer to initial the term, rent, deposit and contract sections before signing. Secure link: in an owner\'s or tenant\'s Documents window press Email secure link (sends them an email) or Get link and WhatsApp text (copy the link or the ready-made message into WhatsApp). The link opens a private page with no login that shows contracts to sign, documents to upload (take a photo or upload), invoices and rent to pay by card, and files you shared. It works for 14 days; a new press gives a fresh link. Templates accept a Word (.docx) or a PDF: Staff Centre, Documents, Templates, open a template, press Upload Word or PDF (admins only). A PDF is read as text, up to 4 MB, and turned into headings and paragraphs you can edit, so check the wording and layout after; a scanned PDF (a picture of pages) has no text and is refused, use the Word version instead. Automatic rules: on the Documents page press Automatic rules (admins change them). Add a rule by choosing when something happens (new tenant added, tenancy created, booking confirmed, client property signed, partner paid, rent 7 days late, lease ends in 60 days) and which template to send, then switch it on. It only acts on events after it is switched on, sends each document once, needs email set up and an email address for the person, is checked daily, and Run now checks straight away. Templates: press Templates at the top of the Documents page. Utilities tracker: Real Estate Intelligence, Operations, Utilities has two views. Tracker shows each property as cards, one per bill account such as electricity (JPS) and internet (Flow), with the latest bill, the change on the last bill (marked high at 30 percent or more), paid, due or overdue status, a 12 bill chart, usage if you enter it, and an Open JPS or Open Flow button to the supplier\'s site. Press Add bill on a card to enter the amount, bill date, due date, usage and optionally the PDF or photo of the bill; Bills lists the history where you can mark paid or unpaid or delete. Owner sees and Tenant sees tick boxes decide who can see each account; owners are shown by default and tenants only when ticked. Accounts is the list where you add or edit an account (service, supplier, account number, monthly amount, next bill date). Owners see Utilities as a tab in their portal and tenants in theirs, read only, and on their secure link. Automatic bills: JPS and Flow have no feed we can connect to, but both email bills, so each bill account has its own bill inbox address (shown on its card, with a Copy button, in the form bills+code at the platform email domain). Set that address as the e-bill email on the JPS or Flow account, or set a forwarding rule in your email so each bill is forwarded to it. When a bill arrives, the amount, bill date, due date and usage are read from the email or its PDF or photo and added by themselves (marked From email), the next bill date updates, and you get a notification. A bill is not added, and you are told instead, when it is for a different account number, in a different currency, is not a bill, or cannot be read; add those by hand. Duplicates are skipped. Bills are not marked paid automatically. It needs inbound email set up (the same Resend inbound that handles replies) and the AI key. Finding it: Human Intelligence Hub, Clients and sales, Owners & Tenants, then the Documents tab along the top. New client link (for someone not in the system yet): Staff Centre, Documents, press New client link at the top. Choose owner or tenant, Property Management or Estate Agency, the contract they sign (a template that needs a signature, optional), and whether to ask for ID and documents, then press Create link and copy the link or the WhatsApp message. They open it on their phone, enter name, email, phone and property, upload documents, then read, initial and sign the contract. Their owner or tenant record is created as soon as they save their details (it may be left behind if they stop part way), their uploads wait in Documents under To review, the signed contract files itself in their Documents, and you get a notification. The list under Create link shows each link as Not opened, In progress, Finished or Expired. When you pick an agreement on the link it shows in their Documents step as Management agreement, Ready to sign, and they read and sign it in the next step; if you pick none it shows We\'ll add this and you add it yourself afterwards. The management agreement (owners) and tenancy agreement (tenants) are not something they upload: they show as We\'ll add this with no upload button, are not counted in their documents to do, and are left out of reminder emails. You add the generated contract yourself in the owner\'s or tenant\'s Documents window, or they sign it in the Sign step when you chose a contract on the link. Press Copy link beside any link not yet finished or expired to copy it again (the latest 20 are listed). Links last 14 days; anyone holding one can fill it in, so send it only to that person. A finished client can then be sent a secure link as usual. Contracts and invoices appear on it when they were sent to that person from Staff Centre, Documents or Finance, Invoices (pick the person from the list). Pay now by card needs Stripe connected under Settings, Payments, and the invoice marked as sent; paid invoices mark themselves paid, other invoices can still be paid by bank transfer. Chase and automatic reminder emails now use the secure link too. Anyone holding the link can see that person\'s documents until it expires, so send it only to them.',
    'Electricity limit: on each electricity account card (Real Estate Intelligence, Operations, Utilities, Tracker) set Covered limit per bill, for example J$7,000 on furnished properties, press Save limit, or Apply to all electricity to set it on every electricity account. The card then shows a bar of what the company covers and what the tenant pays above the limit, and the tenant sees it as Your share in their portal. On a bill in the Bills list, Invoice tenant creates a draft invoice to the property\'s tenant for the part above the limit; review and send it from Invoices. Limits: one limit per account, applied to each bill separately, and the invoice goes to the most recently added tenant on that property.',
    'Partners portal: partners sign in at /partners and see Dashboard, Investments, Payouts, Maintenance, Documents, Deal Analyser and Broadcast. Staff manage them in Staff Centre, Partners, Partners tab: each partner card has Investment (set the amount invested, the currency, the first repayment date and either a fixed monthly repayment or a share of monthly net income, then Save and build schedule; press Mark paid on each month, press Edit on any month to change its date or amount (or Remove it), and Add a month; the partner sees every change at once; months already paid are kept when you rebuild), Documents (upload the signed agreement and other files; hide or show each file to the partner; approve or reject files a partner uploads) and Access. Long-term (on the card: tick the property management properties this partner is in) feeds the Long term dashboard. On the Dashboard tab partners switch between Short term and Long term: Long term shows rent collected, paid on time, rent due against collected and their tenancies. Partners see Maintenance for every property linked to them: each issue shows Reported, In progress and Solved, updated from the same maintenance list staff use. Choose each partner\'s currency (J$, £, US$, €, CA$ or AED) in the Investment panel; amounts show in it. Limits: the repayment schedule is built from the amount and plan you enter, it does not move money; Maintenance covers both their short stay and long-term properties. Partners are listed under their own Partners group in Settings, Portal Access.',
    'AI Assistant: open Human Intelligence Hub, then AI Assistant. Under Knowledge & hours, set your company name, time zone and opening hours and write what it should know about your services, areas, fees and viewings; it only states what you write there. Under Channels (admins only), switch it on for email, tenant and landlord messages and website chat. Use Try it to test, and Activity to see what it handled and deal with anything marked Need follow-up. Limits: it never changes records or takes payments, and phone answering is not switched on yet.',
    'View only: in Settings, Team Management, Edit team member (and when inviting or creating someone) tick View only. In Staff Centre, Partners, Access on a partner card there is the same tick. A view-only person can open every tab and module you gave them but cannot add, edit, delete, upload or mark anything; the database and the server both refuse those changes. They can still send messages and replies (inboxes, chat, WhatsApp, SMS, guest messages, broadcasts). They see a yellow View only bar at the top. Limits: for partners it only applies when you tick extra modules or tabs for them; Novourq Cloud AI actions that change data are blocked for view-only people too.',
    'Cleaner jobs: cleaners sign in and see My Tasks on their dashboard; press Open job on a clean to get its checklist (tick each item; the standard list is built in), Before photos and After photos (taken with the phone camera), and a Maintenance needed box. Mark clean complete only works when every item is ticked and there is at least one before and one after photo; it then marks the clean Completed. Maintenance needed is only for things the maintenance team must fix: the cleaner types what is wrong, picks Low to Urgent and adds photos, and it appears at once as an open item in the maintenance list (Reported by cleaner), on the maintenance team\'s dashboard, and in partner and landlord Maintenance tabs for that property. Limits: the checklist wording is the same for every property; photos are stored with the clean and shown to staff on the cleaning task.',
    'Co-hosts: people who host properties they do not own and have us manage them. Find them in Human Intelligence Hub, Clients and sales, Owners & Tenants, Co-hosts (or Staff Centre, Co-hosts). Press Add co-host to enter their details, pick how we are paid (We keep a percentage, They pay us a fee, or As per contract, matching what they signed), the agreement dates and which short-stay properties we manage for them. On each card: Edit, Documents (ID, the owner\'s consent to host, proof of address, bank details; the co-hosting agreement is added by us), View portal and Create login (an email and password you give them). New client link lets you pick A co-host so they fill in their own details, upload documents and sign the agreement you choose; their record is created for you. When they sign in they land in the Co-host portal with Overview (properties, bookings, booking revenue and, when we keep a percentage, their share), Bookings, Maintenance (each issue at their properties from Reported to Solved), Agreement and Documents. Limits: the share shown is a simple percentage of booking revenue before any expenses; fee and per-contract arrangements show the terms only and do not calculate payouts; maintenance shown is for short-stay properties.',
    'Bank accounts: Staff Centre, Documents, press Bank accounts at the top. Admins add or edit the company\'s bank accounts (bank, account name, number, branch or sort code, currency, payment reference) and mark each as Deposits (client account) or Rent and other payments; other staff can see them. In a template, the blanks Deposit bank details and Payment bank details (group Bank accounts) fill in from this list, using the tenant\'s currency when one matches (Jamaican properties use JMD), so changing the bank here changes every new document. Documents already sent keep the details they went out with. A switched-off account is not shown.',
    'Tenant onboarding: Human Intelligence Hub, Clients and sales, Owners & Tenants, Tenant onboarding. It lists the pack every new tenant gets: Client information sheet, Lease agreement with security deposit scheme, Your security deposit guide, How to rent in Jamaica, Payment instructions, Tenant portal guide and Welcome letter. Press Send pack on a tenant (Property Management or Estate Agency) to give them every document they have not had; they then see them as separate items in the Onboarding tab of their portal and in Tenant onboarding on their secure link, each marked To sign, Signed or Ready, with Review and sign for the ones that need a signature (the lease asks them to initial and sign). The information sheet, lease, payment instructions and welcome letter are templates you can edit in Documents, Templates; the three PDFs are fixed files. Bank details in the lease and payment instructions fill from Documents, Bank accounts. Limits: sending the pack does not email the tenant, so tell them or send the secure link; the inventory list is not part of the pack yet; the lease text is as supplied and stops at clause 1.5, so check it with your solicitor and add the remaining clauses in the template before real use.',
    'Maintenance jobs: maintenance team members sign in and see their jobs on My Tasks (issues reported by staff, cleaners, guests or tenants for the properties they cover). Press Open job to see the issue, its photos and priority, then Start job (moves it to In progress). When finished, add Before and After photos, write what was done, enter the cost if you want it recorded, and press Mark solved (an after photo and a note are required). Solved shows at once in the staff Maintenance list and in partner and landlord Maintenance tabs. Limits: cost is a number with no currency and is stored on the job only; it does not create an invoice or expense yet.',
    'Cleaners and Maintenance overview: Human Intelligence Hub, Portals, Cleaners & Maintenance. For each team it shows how many people there are, who is on shift today, and counts of open, in progress, done this week and not assigned jobs, plus (maintenance) repair cost recorded this month, a list of each person with their open and done jobs and a View portal link that opens their portal exactly as they see it, and the latest open jobs. Open cleaners portal or Open maintenance portal at the top of each section. Both portals are also listed in Settings, Portal Access. Limits: counts cover current properties only; a job counts for a person only when it is assigned to them; repair cost is the sum of costs entered on solved jobs, in no particular currency.',
    'Landlord onboarding: in Property Management, Landlords tab, press Onboarding on a landlord. It shows a checklist (contact details, ID and proof of ownership, payout details, signed agreement, manager assigned, property linked, portal login) that ticks itself as things are filed, and lets you pick the landlord\'s named manager from your team, set the agreement type (Standard management, Guaranteed rent or Partnership), its start and end dates and the terms the landlord sees, then Mark as onboarded. The new client link in Human Intelligence Hub, Documents, is still how a new landlord first sends their details. Any staff member can send a new client link and add or edit contract templates (Documents, Templates, New template, Upload Word or PDF); a template saved by someone who is not an admin stays a draft until an admin ticks Live, and only admins can delete a template. Landlords see a Getting you set up card on their Dashboard until you mark them onboarded, plus My Manager (name, role, email, phone) and Agreement tabs in their portal; their signed copy is in Documents. Limits: one named manager per landlord; the terms are text you write, they do not calculate payments.',
    'Guest check-in (short lets): in Vacation Rentals, Guest Check-ins. Guests get a link by email 3 days before arrival (reminder 2 days before) and on their phone enter their details, upload a photo ID, save a card for the security deposit and sign the house rules. To switch it on, edit a property and turn on Online check-in, set the Security deposit and the Check-in terms (if empty the house rules are used). You can also press Send link on any booking. The deposit is a saved card, not a hold: nothing is charged unless you press Charge damage (never more than the deposit); Release deposit forgets the card. ID photos are private and deleted 30 days after check-out. Needs Stripe connected for the card step.',
    'When you stop managing a property, open Real Estate Intelligence, then Properties, and press No longer managed (or the same button under Vacation Rentals, Properties). Choose the date and reason. The property leaves your active lists, counts, website and the AI, but its bookings, rent, documents and history are kept. Find it again under the Former filter and press Restore to bring it back. Restoring does not switch its website listing back on. Delete is different: it erases the property for good.',
    'Ask Novourq Cloud AI about money, the books or tax and it answers like a careful property accountant: it shows its workings, labels estimates, flags problems in your books and uses the right country\'s rules. Turn on Search the web so it checks current rates and thresholds. It is an AI, not a qualified accountant, so have your own accountant review VAT returns, accounts and tax filings.',
    'Viewings it books appear in Viewings, and the person receives a confirmation email.',
  ] },
  { id: 'voice', title: 'Novourq Voice', steps: [
    'Press the navy Novourq Voice button at the bottom right of any page to start a call with the AI. Say what you want, such as "add a repair at Oak Court" or "find me two-bed deals in Leeds", and it does it.',
    'The pencil button next to it types what you say into the box you have open. The speaker button turns the AI replying out loud on or off.',
    'In Settings, Voice, choose a Woman or Man voice, add words and shortcuts, and read or delete past call transcripts.',
    'Tenants and landlords have their own version in their portal. It only knows their own records and can report repairs or pass messages to you.',
    'Anything involving money or a contract still waits for your approval.',
  ] },
  { id: 'map', title: 'Map, floors and walk-through', steps: [
    'Open Real Estate Intelligence, then Overview, then Map. Every property and deal the AI found is a pin coloured by status: let, vacant, rent behind, certificate due.',
    'Click a pin to see the tenant, rent and what needs doing. Use the filters, and the UK and Jamaica buttons, to narrow it. Press 3D for a tilted view of the real buildings.',
    'For a property in a building, press View floors to see every flat by floor with its rent and status.',
    'Click a flat, then Add floor plan. Upload the plan and press Read plan with AI, or draw the rooms. Check the sizes and Save rooms.',
    'Then press View in 3D and walk to see a furnished model of the flat. Plan turns the model, Walk is first person, and Tour starts outside the building and then shows a person walking through every room while the camera follows. Save as video records the tour and downloads it. If a property is missing from the map, check its address.',
    'Showcase a development: your Development projects show as teal In development pins (set the project Location). Select one, press View floors for its units by floor with prices, then add each unit floor plan and walk through it in 3D before it is built.',
  ] },
  { id: 'datahub', title: 'Data Hub', steps: [
    'Admins open Human Intelligence Hub, then Oversight, then Data Hub. It shows what is stored, how complete it is, where it came from and what the AI changed.',
    'Tenants and landlords ask to download, correct or delete their data from the My Data tab in their portal. Their requests arrive in the Data Hub, where you mark them completed or declined.',
  ] },
  { id: 'help', title: 'Getting help', steps: [
    'Open the Help Centre in the left menu, just above Settings. Widescreen video walkthroughs sit beside this guide, one for each part of Novourq, including packs and onboarding, the agent programme, website links and careers, your plan and currency, and co-hosts, crew and HR.',
    'Ask the AI panel first. It knows the platform and answers straight away.',
    'Found something broken, or want to leave a review or suggest an idea? Use the Submissions tab in Settings. We read every one and reply there.',
    'News and updates from us appear under System Messages.',
    'On the free trial? The bottom of the left menu shows how many days are left. It turns amber in the last 3 days and disappears once you are on a paid plan.',
    'Beside Properties you will see how many you have used, for example "2 / 3 properties · 3 included, then £12/mo each".',
    'Your plan includes 3 properties. When you add a 4th, you are asked to add one more for £12 a month, and it is added to your plan straight away. Each further property is another £12 a month.',
    'Want to see your plan or change your card? Open Settings, then Payments. If you cancel through Manage billing, the plan box says when it ends and that you keep full access until then. The Your NOVOURQ plan box shows your plan and status, and Manage billing opens a secure page to update your card, see invoices, change plan or cancel.',
  ] },
]

export default function GuidePanel() {
  const [open, setOpen] = useState<string>('start')
  return (
    <div style={{ maxWidth: 700 }}>
      <h2 style={{ fontSize: 20, fontWeight: 700, color: '#323338', margin: '0 0 4px' }}>Step-by-step guide</h2>
      <div style={{ fontSize: 13, color: '#667085', marginBottom: 20 }}>How to get the most out of Novourq, step by step.</div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {SECTIONS.map(s => {
          const isOpen = open === s.id
          return (
            <div key={s.id} style={{ background: '#fff', border: '1px solid #E4E7EC', borderRadius: 12, overflow: 'hidden' }}>
              <button onClick={() => setOpen(isOpen ? '' : s.id)} aria-expanded={isOpen} aria-controls={'guide-' + s.id}
                style={{ display: 'flex', width: '100%', justifyContent: 'space-between', alignItems: 'center', padding: '14px 18px', background: isOpen ? '#F4F9FD' : '#fff', border: 0, cursor: 'pointer', fontSize: 15, fontWeight: 600, color: '#323338', fontFamily: 'inherit', textAlign: 'left' }}>
                {s.title}<span aria-hidden="true" style={{ color: '#98A2B3' }}>{isOpen ? '−' : '+'}</span>
              </button>
              {isOpen && (
                <>
                {s.pic && <img src={s.pic.src} alt={s.pic.alt} style={{ display: 'block', maxWidth: '100%', margin: '4px 16px 8px', border: '1px solid #E4E7EC', borderRadius: 8 }} />}
                <ol id={'guide-' + s.id} style={{ margin: 0, padding: '4px 18px 16px 40px', fontSize: 14, color: '#344054', lineHeight: 1.6 }}>
                  {s.steps.map((t, i) => <li key={i} style={{ marginBottom: 6 }}>{t}</li>)}
                </ol>
                </>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}
